def test_member_rejects_case_insensitive_duplicate_matches():
    with pytest.raises(ValueError, match="ambiguous case-insensitive"):
        member({"stl/x.STL": {"crc": 1}, "STL/X.stl": {"crc": 2}}, "stl", "x", ".stl")
    assert member({"stl/X.STL": {"crc": 1}}, "stl", "x", ".stl") == {"crc": 1}


def write_mesh(root, key, distance=0, ascii_stl=False):
    directory = root / "stl"
    directory.mkdir(parents=True, exist_ok=True)
    mesh = trimesh.creation.box(extents=(10, 10, 10))
    mesh.apply_translation((distance, 0, 0))
    path = directory / f"{key}.STL"
    if ascii_stl:
        path.write_text(trimesh.exchange.stl.export_stl_ascii(mesh), encoding="ascii")
    else:
        mesh.export(path)


@pytest.mark.parametrize("stem,number,neutral,prior_members", GROUPS)
def test_render_consumer_compares_every_old_candidate_with_independent_member_verdicts(
    tmp_path, render_diff, stem, number, neutral, prior_members,
):
    old_root, new_root = tmp_path / "old", tmp_path / "new"
    expected = {}
    for index, (prior, configuration) in enumerate(prior_members.items()):
        # One byte-identical candidate must not hide another translated clone.
        distance = index if neutral == "Default" else 10 * index
        write_mesh(old_root, prior, distance)
        key = mesh_key(stem, configuration)
        if key not in expected:
            write_mesh(new_root, key, 0 if neutral == "Default" else distance,
                       ascii_stl=neutral != "Default")
            expected[key] = {}
        expected[key][prior] = distance if neutral == "Default" else 0
    old, new = render_diff.LocalSource(old_root), render_diff.LocalSource(new_root)
    pairs = paired_keys(old.mesh_keys(), new.mesh_keys(), load_identity_map())
    changed, deviations = render_diff.classify(old, new, set(new.mesh_keys()), pairs, jobs=1)
    assert changed == ({stem} if neutral == "Default" else set())
    assert set(deviations) == set(expected)
    for key, sources in expected.items():
        assert deviations[key] == pytest.approx(sources, abs=0.01)


def test_render_unrelated_t006_is_not_hidden_by_other_variants(tmp_path, render_diff):
    old_root, new_root = tmp_path / "old", tmp_path / "new"
    write_mesh(old_root, "cone-gear--t006")
    write_mesh(new_root, "dt-cone-gear--t006", ascii_stl=True)
    write_mesh(old_root, "cone-gear--t024")
    write_mesh(new_root, "dt-cone-gear--t048")
    old, new = render_diff.LocalSource(old_root), render_diff.LocalSource(new_root)
    pairs = paired_keys(old.mesh_keys(), new.mesh_keys(), load_identity_map())
    changed, deviations = render_diff.classify(old, new, set(new.mesh_keys()), pairs, jobs=1)
    assert changed == {"dt-cone-gear--t048"}
    assert deviations["dt-cone-gear--t006"]["cone-gear--t006"] < 0.01
    assert deviations["dt-cone-gear--t048"] == {}


def test_mesh_deviation_uses_actual_cache_basenames(tmp_path, monkeypatch):
    import release_diff

    monkeypatch.setattr(release_diff, "CACHE", tmp_path)
    for tag, key, distance in (("before", "pd-vn-chain-outer-link", 0),
                               ("after", "sh-vn-chain-link--outerlink", 2)):
        write_mesh(tmp_path / tag, key, distance)
        (tmp_path / tag / "stl" / f"{key}.STL").rename(tmp_path / tag / f"{key}.stl")
    assert mesh_deviation("before", "after", "pd-vn-chain-outer-link",
                          "sh-vn-chain-link--outerlink")["hausdorff_mm"] == pytest.approx(2)


@pytest.mark.parametrize("parts", ["pd-vn-chain-outer-link", "chain-outer-link", "sh-vn-chain-link--OuterLink"])
def test_release_cli_inventories_configured_stl_without_step_and_explicitly_skips_boolean(
    tmp_path, monkeypatch, capsys, parts,
):
    import release_diff

    old = {"step/pd-vn-chain-outer-link.STEP": {"crc": 1, "uncomp": 100},
           "stl/pd-vn-chain-outer-link.STL": {"crc": 2, "uncomp": 50}}
    new = {"step/sh-vn-chain-link.STEP": {"crc": 3, "uncomp": 100},
           "stl/sh-vn-chain-link--outerlink.STL": {"crc": 4, "uncomp": 50}}
    monkeypatch.setattr(release_diff, "central_dir", lambda url: old if "before/" in url else new)
    monkeypatch.setattr(release_diff, "CACHE", tmp_path)
    extracted, compared = [], []
    monkeypatch.setattr(release_diff, "extract", lambda url, entry, dest: extracted.append(dest))
    result = dict(hausdorff_mm=0, mean_dev_mm=0, vol_a_mm3=1, vol_b_mm3=1,
                  tris_a=12, tris_b=12, bbox_a=[1, 1, 1], bbox_b=[1, 1, 1])
    monkeypatch.setattr(release_diff, "mesh_deviation", lambda *args: compared.append(args) or result)
    monkeypatch.setattr(release_diff, "boolean_cut", lambda *args: pytest.fail("missing STEP was used"))
    monkeypatch.setattr(sys, "argv", ["release_diff.py", "before", "after", "--parts", parts])
    release_diff.main()
    output = capsys.readouterr().out
    assert compared == [("before", "after", "pd-vn-chain-outer-link", "sh-vn-chain-link--outerlink")]
    assert "(3c) mesh:" in output and "IDENTICAL (within mesh tol)" in output
    assert "(3b) solid:   SKIPPED (member missing from a bundle)" in output
    assert tmp_path / "after" / "sh-vn-chain-link.step" not in extracted


def test_release_cli_does_not_discard_old_clone_comparisons(monkeypatch, capsys):
    import release_diff

    sources = tuple(GROUPS[1][3])
    target = GROUPS[1][0]
    old = {f"step/{key}.STEP": {"crc": 1, "uncomp": 100} for key in sources}
    new = {f"step/{target}.STEP": {"crc": 1, "uncomp": 100}}
    monkeypatch.setattr(release_diff, "central_dir", lambda url: old if "before/" in url else new)
    monkeypatch.setattr(release_diff, "member", lambda *args: None)
    monkeypatch.setattr(sys, "argv", ["release_diff.py", "before", "after", "--parts", sources[0]])
    release_diff.main()
    output = capsys.readouterr().out
    assert {line for line in output.splitlines() if line.startswith("### ")} == {
        f"### {target} <- {source}" for source in sources
    }
    assert "deleted parts: (none)" in output


