@pytest.mark.parametrize("directory,extension", [("gltf", ".glb"), ("boxes", ".json"), ("pdf", ".pdf")])
def test_pose_consumer_reuses_unique_prior_member_without_contacting_github(
    tmp_path, monkeypatch, directory, extension,
):
    import pose_to_meshprobe

    monkeypatch.setattr(pose_to_meshprobe, "CAD_OUT", tmp_path)
    cache = tmp_path / "release-cache" / "v50"
    cache.mkdir(parents=True)
    name = f"{directory}/vn-fillister-screw{extension}"
    with ZipFile(cache / "harmonic-analyzer-v50.zip", "w") as archive:
        archive.writestr(name, b"immutable historical member")
    monkeypatch.setattr(pose_to_meshprobe, "_gh", lambda args: pytest.fail("cached bundle is complete"))
    for target in [GROUPS[1][0], *GROUPS[1][3]]:
        actual = pose_to_meshprobe.release_member(f"{directory}/{target}{extension}", "v50")
        assert actual == cache / name
        assert actual.read_bytes() == b"immutable historical member"


@pytest.mark.parametrize("cached_first", [False, True])
@pytest.mark.parametrize("directory,extension", [("gltf", ".glb"), ("boxes", ".json"), ("pdf", ".pdf")])
def test_pose_consumer_rejects_ambiguous_clone_sources_even_after_one_was_cached(
    tmp_path, monkeypatch, cached_first, directory, extension,
):
    import pose_to_meshprobe

    monkeypatch.setattr(pose_to_meshprobe, "CAD_OUT", tmp_path)
    cache = tmp_path / "release-cache" / "v50"
    cache.mkdir(parents=True)
    with ZipFile(cache / "harmonic-analyzer-v50.zip", "w") as archive:
        for prior in GROUPS[1][3]:
            archive.writestr(f"{directory}/{prior}{extension}", prior.encode("ascii"))
    if cached_first:
        cached = cache / directory / f"dt-vn-fillister-screw{extension}"
        cached.parent.mkdir()
        cached.write_bytes(b"first extracted source is not authoritative")
    monkeypatch.setattr(pose_to_meshprobe, "_gh", lambda args: pytest.fail("cached bundle is complete"))
    with pytest.raises(ValueError, match="ambiguous prior identity"):
        pose_to_meshprobe.release_member(f"{directory}/{GROUPS[1][0]}{extension}", "v50")


@pytest.mark.parametrize("stem,number,neutral,prior_members", [g for g in GROUPS if g[2] != "Default"])
def test_pose_consumer_selects_exact_chain_wire_and_kit_member(
    tmp_path, monkeypatch, stem, number, neutral, prior_members,
):
    import pose_to_meshprobe

    monkeypatch.setattr(pose_to_meshprobe, "CAD_OUT", tmp_path)
    cache = tmp_path / "release-cache" / "v50"
    cache.mkdir(parents=True)
    with ZipFile(cache / "harmonic-analyzer-v50.zip", "w") as archive:
        for prior in prior_members:
            archive.writestr(f"gltf/{prior}.glb", prior.encode("ascii"))
    monkeypatch.setattr(pose_to_meshprobe, "_gh", lambda args: pytest.fail("cached bundle is complete"))
    for prior, configuration in prior_members.items():
        actual = pose_to_meshprobe.release_member(f"gltf/{mesh_key(stem, configuration)}.glb", "v50")
        assert actual == cache / f"gltf/{prior}.glb"
    actual = pose_to_meshprobe.release_member(f"gltf/{stem}.glb", "v50")
    assert actual.stem == next(prior for prior, configuration in prior_members.items() if configuration == neutral)
    with pytest.raises(SystemExit, match="bundles no"):
        pose_to_meshprobe.release_member(f"gltf/{stem}--default.glb", "v50")


