def test_explicit_native_namespace_matches_only_exact_supplied_name2_evidence(framing_consumer):
    name = "ha-harmonic-analyzer/sh-vn-chain-link-42"
    camera = {"frame_components": [name], "occurrenceNamespace": "native-name2"}
    target, _ = framing_consumer.resolve_framing(
        camera, [(name, [10, 20, 30, 20, 30, 40])], (0, 0, 0), (100, 100, 100),
    )
    assert target == (15, 25, 35)
    # A same-number leaf elsewhere is not evidence for this qualified native path.
    target, _ = framing_consumer.resolve_framing(
        camera, [("other/sh-vn-chain-link-42", [10, 20, 30, 20, 30, 40])],
        (0, 0, 0), (100, 100, 100),
    )
    assert target == (50, 50, 50)


